(function(){'use strict';function closeThemeOverlays(){try{document.documentElement.classList.remove('wd-close-side-opened','wd-scroll-lock');document.body.classList.remove('wd-scroll-lock','wrapper-locked');document.querySelectorAll('.wd-close-side.wd-opened,.wd-side-hidden.wd-opened,.cart-widget-side.wd-opened,.mobile-nav.wd-opened,.wd-search-full-screen.wd-opened').forEach(function(el){el.classList.remove('wd-opened')});if(typeof jQuery!=='undefined'){jQuery('.mfp-ready,.mfp-bg,.mfp-wrap').remove();jQuery('html').removeClass('mfp-zoom-out-cur mfp-ready')}}catch(e){}}function bind(){if(!window.SLL||!window.SLL.swup||!window.SLL.swup.hooks)return false;var hooks=window.SLL.swup.hooks;if(window.SLL.swup._sllWoodmartBound)return true;window.SLL.swup._sllWoodmartBound=true;hooks.on('visit:start',closeThemeOverlays);hooks.on('page:view',function(){closeThemeOverlays();setTimeout(closeThemeOverlays,50);setTimeout(closeThemeOverlays,200)});return true}function boot(){if(bind())return;document.addEventListener('sll:ready',bind);setTimeout(bind,400);setTimeout(bind,1500)}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',boot)}else{boot()}})();